Author:     welpy-cw <h.w.forms@arcor.de>
AuthorDate: Wed Feb 26 10:16:52 2025 +0000
Commit:     welpy-cw <h.w.forms@arcor.de>
CommitDate: Wed Feb 26 10:16:52 2025 +0000

    Bug 1950021 - Fix regression from bug 1941332. r=mkmelin,BenC


    - In `findMsgIdInFolder()`, close only those databases that weren't already open.
    - Rename `closeDBIfFolderNotOpen()` to `closeDB()`, remove it from the `nsIMsgFolder` interface, and make it a protected method of `class nsMsgDBFolder` (reverting some changes from bug Bug 1787609).

    Differential Revision: https://phabricator.services.mozilla.com/D239280

diff --git a/mail/modules/MailUtils.sys.mjs b/mail/modules/MailUtils.sys.mjs
index 323c33bcb26..00d8609f70f 100644
--- a/mail/modules/MailUtils.sys.mjs
+++ b/mail/modules/MailUtils.sys.mjs
@@ -767,13 +767,17 @@ export var MailUtils = {
     // Search in folder.
     if (!folder.isServer) {
       try {
+        const weOpenedDB = !folder.databaseOpen;
         msgHdr = folder.msgDatabase.getMsgHdrForMessageID(msgId);
         if (msgHdr) {
           return msgHdr;
         }
-        folder.closeDBIfFolderNotOpen(true);
+        if (weOpenedDB) {
+          folder.msgDatabase.forceClosed();
+          folder.msgDatabase = null;
+        }
       } catch (ex) {
-        console.error(`Database for ${folder.name} not accessible`);
+        console.error(`Database for ${folder.URI} not accessible`);
       }
     }

diff --git a/mailnews/base/public/nsIMsgFolder.idl b/mailnews/base/public/nsIMsgFolder.idl
index fdeb245e4e9..dd126993bf5 100644
--- a/mailnews/base/public/nsIMsgFolder.idl
+++ b/mailnews/base/public/nsIMsgFolder.idl
@@ -588,9 +588,6 @@ interface nsIMsgFolder : nsISupports {
    */
   attribute nsIMsgDatabase msgDatabase;

-  /// Close the database if not open in folder.
-  void closeDBIfFolderNotOpen(in boolean forceClosed);
-
   /// Does the folder have a local reference to the msgDatabase?
   readonly attribute boolean databaseOpen;

diff --git a/mailnews/base/src/nsMsgDBFolder.cpp b/mailnews/base/src/nsMsgDBFolder.cpp
index de5dfeae8b4..ed2ce712115 100644
--- a/mailnews/base/src/nsMsgDBFolder.cpp
+++ b/mailnews/base/src/nsMsgDBFolder.cpp
@@ -672,7 +672,7 @@ nsresult nsMsgDBFolder::ReadDBFolderInfo(bool force) {
           NS_ENSURE_SUCCESS(rv, rv);
           if (hasnew) db->SortNewKeysIfNeeded();
         }
-        if (weOpenedDB) CloseDBIfFolderNotOpen(false);
+        if (weOpenedDB) CloseDB();
       }
     } else {
       // we tried to open DB but failed - don't keep trying.
@@ -1957,7 +1957,7 @@ nsMsgDBFolder::GetStringProperty(const char* propertyName,
       rv = GetDBFolderInfoAndDB(getter_AddRefs(folderInfo), getter_AddRefs(db));
       if (NS_SUCCEEDED(rv))
         rv = folderInfo->GetCharProperty(propertyName, propertyValue);
-      if (weOpenedDB) CloseDBIfFolderNotOpen(false);
+      if (weOpenedDB) CloseDB();
       if (NS_SUCCEEDED(rv)) {
         // Now that we have the value, store it in our cache.
         if (cacheElement) {
@@ -4378,7 +4378,7 @@ nsresult nsMsgDBFolder::ApplyRetentionSettings(bool deleteViaFolder) {
   // we don't want applying retention settings to keep the db open, because
   // if we try to purge a bunch of folders, that will leave the dbs all open.
   // So if we opened the db, close it.
-  if (weOpenedDB) CloseDBIfFolderNotOpen(false);
+  if (weOpenedDB) CloseDB();
   return rv;
 }

@@ -4834,9 +4834,8 @@ NS_IMETHODIMP nsMsgDBFolder::NotifyCompactCompleted() {
   return NS_OK;
 }

-NS_IMETHODIMP nsMsgDBFolder::CloseDBIfFolderNotOpen(bool aForceClosed) {
+nsresult nsMsgDBFolder::CloseDB() {
   if (!(mFlags & (nsMsgFolderFlags::Trash | nsMsgFolderFlags::Inbox))) {
-    if (aForceClosed && mDatabase) mDatabase->ForceClosed();
     SetMsgDatabase(nullptr);
   }
   return NS_OK;
